import{F as e,_ as t,f as n,h as r,j as i,n as a}from"./chunks/shared.rYHlazZf.js";var o=JSON.parse(`{"title":"自動化を整理する","description":"","frontmatter":{"title":"自動化を整理する","docId":"user.automations.index","translationKey":"user.automations.index","locale":"ja","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"08bb26a20687b58094e908a4e8395abeae3b9adc3932c86d9c3b08f5ebbf8ce3","translationRevision":"162a454d168e0cc1cd00af24d3c72645f9aa44762f8fad19cba79a5cfb943a45","order":10},"headers":[],"relativePath":"ja/user/automations/index.md","filePath":"ja/user/automations/index.md","lastUpdated":1795735295000}`),s={name:`ja/user/automations/index.md`};function c(a,o,s,c,l,u){let d=e(`DemoFrame`);return i(),n(`div`,null,[o[0]||=r(`<h1 id="organize-automations" tabindex="-1">自動化を整理する <a class="header-anchor" href="#organize-automations" aria-label="Permalink to “自動化を整理する”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目的と前提条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “目的と前提条件”">​</a></h2><p>LIVE のイベントに反応する、小さく分かりやすいライブラリを作ります。正常に動くデスクトップホストが必要です。配信元のイベントの検証には実際の <a href="./../live/connections.html">LIVE 接続</a> が、プラグインのアクションには対応するプラグインとサービスの準備も必要です。</p><h2 id="understand-the-library" tabindex="-1">ライブラリの仕組み <a class="header-anchor" href="#understand-the-library" aria-label="Permalink to “ライブラリの仕組み”">​</a></h2><p><strong>アクション</strong> はログ出力や音の再生など、設定を再利用できる処理です。<strong>イベント</strong> はトリガー、フィルター、クールダウン、関連アクションを指定します。プロファイルは用途ごとに定義をまとめ、一度に有効になるプロファイルパックは1つです。実行時の<a href="./variables.html">変数</a> を使うと、複数のアクションで値を共有できます。</p><ol><li><strong>自動化</strong> を開き、編集前にアクティブなプロファイルを確認します。イベントとアクションは別々に検索し、選ぶレコードの種類を把握します。</li><li><a href="./first-rule.html">最初のログ記録ルール</a> から始めます。先にアクションを作り、それを参照するイベントを作成します。</li><li>現在のホストが対応するトリガーを選び、フィールド選択から対応するフィルターを追加します。複数条件は一致範囲を絞りますが、受信ペイロードは変更しません。</li><li>クールダウンと適用範囲を設定します。全体のクールダウンは全視聴者を通じてルールを制限し、ユーザー別では視聴者ごとに管理します。</li><li>目的のアクションを順に関連付けます。通常モードは選んだ一覧を実行し、ランダムモードはその中から1つ選びます。遅延アクションは後続処理を遅らせますが、LIVE の取り込みは遅らせません。</li><li>保存して表示された定義の変更を確認し、実行するレコードを明示的に有効にします。履歴でアクション名、結果、エラーを確認します。</li></ol><p>すべての比較で単一の値の代わりに値のリストを指定できます。既定の結合は「いずれか」で、少なくとも1つの値が一致すれば条件を満たします。すべての値の一致が必要な場合は量指定子を「すべて」に変更します。「ではない」の場合は「どれでもない」と読みます。条件にはキャプチャエイリアスも付けられ、勝った値はアクションテンプレートで <code>{{ match.&lt;alias&gt; }}</code>（エイリアスがなければ <code>{{ match.&lt;位置&gt; }}</code>）として使えます。常に必須の条件の下に、最大4つの<strong>代替</strong>を追加できます。各グループ内の条件はすべて満たす必要があり、いずれか1つのグループが満たされればイベントは発火します。</p><p>テストでも設定した処理が実行されます。特に音声、HTTP、ポイント、プラグインでは、<strong>テストを実行</strong> やイベント実行の前に選択中のアクション一覧を読んでください。学習中はログを使います。</p><h2 id="expected-result-and-status" tabindex="-1">期待される結果と提供状況 <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to “期待される結果と提供状況”">​</a></h2><p>ローカル編集、実行、テンプレート、プロファイル、履歴を利用できます。プラグインのトリガーは対応プラグインがインストールされ有効な間だけ表示されます。有効状態はインポート経路と確認済み enabled 値によります。確定前にイベントとアクションを確認してください。イベント／アクションの <strong>変更</strong> は<a href="./../cloud/changes.html">ローカルの基準との比較</a> であり、Cloud への自動アップロードではありません。</p><h2 id="recovery" tabindex="-1">問題が起きたとき <a class="header-anchor" href="#recovery" aria-label="Permalink to “問題が起きたとき”">​</a></h2><p>実行されない場合は、アクティブなプロファイル、有効状態、トリガー、フィルター、クールダウン、欠けたアクションの順に確認します。リビジョンが競合したら、現在の保存済み定義を読み直して再確認します。他の人の更新を無条件に上書きしないでください。大きな変更の前に、正常な<a href="./templates.html">プロファイル</a> をエクスポートします。</p><h2 id="operational-details" tabindex="-1">運用の詳細 <a class="header-anchor" href="#operational-details" aria-label="Permalink to “運用の詳細”">​</a></h2><p>取り込み・切り替え前に<a href="./templates.html#operational-details">経路ごとの有効化規則</a>を読みます。個別に無効化した項目も再び有効になる場合があります。cooldown はメモリ内で最大 24 時間、uniqueId 不在の視聴者は匿名範囲を共有します。保持キー 8,192 件で表を空にするため、過負荷や再起動で追加実行が起こり得ます。永続 quota・replay 保証ではありません。</p><p>実際の設定に触れる前にインタラクティブに試せます:</p>`,15),t(d,{scenario:`automation`,locale:`ja`,panel:`automation`,title:`自動化ワークスペースを試す`}),o[1]||=r(`<h2 id="command-line-operations" tabindex="-1">コマンドライン操作 <a class="header-anchor" href="#command-line-operations" aria-label="Permalink to “コマンドライン操作”">​</a></h2><p>このガイドのすべての操作はCLIからも利用できます——オフライン、スクリプト可能、エージェント対応。使用法の行はパーサー構文であり、すべての言語で英語のままです。</p><table tabindex="0"><thead><tr><th>コマンド</th><th>概要</th></tr></thead><tbody><tr><td><code>tiktools automation list [--kind event&amp;#124;action&amp;#124;all]</code></td><td>自動化ルールを一覧表示</td></tr><tr><td><code>tiktools automation context [--event-type t]</code></td><td>ルールで利用可能なテンプレートコンテキスト</td></tr><tr><td><code>tiktools automation get &lt;id&gt; [--kind event&amp;#124;action]</code></td><td>ルールを1つ読み取る</td></tr><tr><td><code>tiktools automation create --record json [--kind event&amp;#124;action]</code></td><td>ルールを作成</td></tr><tr><td><code>tiktools automation update &lt;id&gt; --record json [--kind event&amp;#124;action]</code></td><td>ルールを更新</td></tr><tr><td><code>tiktools automation delete &lt;id&gt; [--kind event&amp;#124;action]</code></td><td>ルールを削除 <strong>破壊的</strong></td></tr><tr><td><code>tiktools automation enable &lt;id&gt; [--kind event&amp;#124;action]</code></td><td>ルールを有効化</td></tr><tr><td><code>tiktools automation disable &lt;id&gt; [--kind event&amp;#124;action]</code></td><td>ルールを無効化</td></tr><tr><td><code>tiktools automation test (--id &lt;id&gt; &amp;#124; --record json) [--kind event&amp;#124;action] [--trigger t] [--event json]</code></td><td>サンプルイベントに対してルールをドライラン</td></tr><tr><td><code>tiktools automation fire --trigger &lt;type&gt; [--event json] [--record json]</code></td><td>トリガーを手動で発火</td></tr><tr><td><code>tiktools automation moderation-penalty --points &lt;delta&gt;</code></td><td>ポイントでモデレーションペナルティを適用</td></tr></tbody></table><table tabindex="0"><thead><tr><th>コマンド</th><th>概要</th></tr></thead><tbody><tr><td><code>tiktools workflow list</code></td><td>保存されたワークフローグラフを一覧表示</td></tr><tr><td><code>tiktools workflow get &lt;id&gt;</code></td><td>グラフを1つ読み取る</td></tr><tr><td><code>tiktools workflow save --record json</code></td><td>グラフを作成または置換</td></tr><tr><td><code>tiktools workflow delete &lt;id&gt;</code></td><td>グラフを削除 <strong>破壊的</strong></td></tr><tr><td><code>tiktools workflow enable &lt;id&gt;</code></td><td>グラフを有効化</td></tr><tr><td><code>tiktools workflow disable &lt;id&gt;</code></td><td>グラフを無効化</td></tr></tbody></table><p>規約、JSON出力、破壊的操作のマーカーについては<a href="./../../developer/cli.html">完全なコマンドリファレンス</a>を参照してください。</p>`,5)])}var l=a(s,[[`render`,c]]);export{o as __pageData,l as default};